// Account balance lookups against an injected database connection.
function balance(database, account) {
  return database.query("SELECT balance FROM accounts WHERE account = '" + account + "'", []);
}

module.exports = { balance };

const accounts = require('../lib/accounts');

test('returns rows', () => {
  const database = { query: () => [[25]] };
  expect(accounts.balance(database, 'alice')).toEqual([[25]]);
});
